// Every mission includes a reference solution and executable validation.
const WORLDS=[
{name:'Эхлэлийн арал',icon:'🌱',color:'#b8ef83',desc:'Анхны мөрөөс өөрийн хувьсагч хүртэл'},
{name:'Сонголтын ой',icon:'🌲',color:'#7adbc4',desc:'Нөхцөл шалгаж, зөв замаа сонго'},
{name:'Давталтын уул',icon:'⛰️',color:'#a9baff',desc:'Давтагдах үйлдлийг коддоо даатга'},
{name:'Эрдэнэсийн агуй',icon:'💎',color:'#d9adf5',desc:'Жагсаалт, текст, өгөгдөлтэй ажилла'},
{name:'Функцийн цайз',icon:'🏰',color:'#ffce72',desc:'Өөрийн чадвараа бүтээж, цайзыг эзэл'}];
const MISSIONS=[];
function lesson(world,title,concept,info,task,start,solution,expected,check,hints,extra={}){MISSIONS.push({id:MISSIONS.length,world,title,concept,info,task,start,solution,expected,check,hints,...extra})}
lesson(0,'Сайн уу, Python!','print()', 'Код бол компьютерт өгөх заавар. print() хаалт доторх мэдээллийг дэлгэцэд гаргана. Текстийг " " эсвэл \' \' хашилтад бичдэг. Жишээ: print("Сайн уу!").','Сайн уу, Python! гэсэн мэндчилгээг хэвлэ.','# Анхны кодоо энд бичээрэй\n','print("Сайн уу, Python!")','Сайн уу, Python!','assert has("Call"), "print() ашиглаарай."',['print() функц ашиглана.','print("Сайн уу, Python!")']);
lesson(0,'Хоёр мөрийн захиа','Дараалал','Python кодыг дээрээс доош ажиллуулна. print() бүр шинэ мөр гаргана. # тэмдгээр эхэлсэн тайлбарыг ажиллуулахгүй.','Эхний мөрөнд Би суралцаж байна, дараагийн мөрөнд Би чадна! гэж хэвлэ.','# Хоёр print() бичээрэй\n','print("Би суралцаж байна")\nprint("Би чадна!")','Би суралцаж байна\nБи чадна!','assert count("Call") >= 2, "Хоёр print() дуудаарай."',['Нэг өгүүлбэрт нэг print() ашигла.','Хоёр дахь print() нь шинэ мөрөнд, доголгүй байна.']);
lesson(0,'Аялагчийн нэр','Хувьсагч','Хувьсагч бол утга хадгалах нэртэй хайрцаг. name = "Ану" нь name нэрэнд текст онооно. print(name) нь нэрийн утгыг хэвлэнэ.','name хувьсагчид Болд гэж хадгалж хэвлэ.','name = ""\nprint(name)','name = "Болд"\nprint(name)','Болд','assert g.get("name") == "Болд", "name хувьсагчийн утгыг шалгаарай."',['Хувьсагчийн нэрийг print дотор хашилтгүй бичнэ.','name = "Болд"']);
lesson(0,'Зоосны тооцоо','Тоо ба үйлдэл','Тоонд хашилт хэрэггүй. + нэмнэ, - хасна, * үржүүлнэ, / хуваана. Жишээ: coins = 5 + 2.','12 дээр 8-ыг нэмээд coins хувьсагчид хадгал. Дараа нь хэвлэ.','coins = 0\nprint(coins)','coins = 12 + 8\nprint(coins)','20','assert has("BinOp") and g.get("coins") == 20, "Нэмэх үйлдлээр coins-ийг бодоорой."',['coins = 12 + 8 гэж бичиж болно.','Нийлбэрээ print(coins) гэж хэвлэнэ.']);
lesson(0,'Өөрийн мэндчилгээ','f-string','f-string нь текст дотор хувьсагчийн утга оруулна. Текстийн өмнө f, утгын эргэн тойронд { } хэрэглэнэ. Жишээ: f"Сайн уу, {name}!".','hero = "Ану" ашиглан Сайн уу, Ану! гэж хэвлэ.','hero = "Ану"\n# f-string ашиглаарай\n','hero = "Ану"\nprint(f"Сайн уу, {hero}!")','Сайн уу, Ану!','assert has("JoinedStr"), "f-string ашиглаарай."',['print(f"...") хэлбэрээр бичнэ.','Нэр орох хэсэгт {hero} гэж бичнэ.']);
lesson(0,'Анхны гүүр','Кодоор алхах','Тоглоомын move() команд баатрыг зүүнээс баруун тийш нэг нүд хөдөлгөнө. collect() нь тухайн нүдний зоосыг авна. Эдгээр нь энэ тоглоомын тусгай Python функцүүд.','3 удаа move() дуудаж зоосонд хүрээд collect() дуудаарай.','# Гүүрээр алхаарай\n','move()\nmove()\nmove()\ncollect()','', 'assert has("Call")',['move() бүр нэг нүд урагшилна.','move()-г 3 удаа, дараа нь collect() дуудаарай.'],{game:{width:6,start:0,coins:[3],goal:3},boss:true});
lesson(1,'Нууц хаалга','if','if нөхцөл: хэлбэрээр бичээд доторх үйлдлийг 4 зайгаар доголлоно. >= нь их буюу тэнцүү гэсэн харьцуулалт.','keys 3-аас багагүй үед Хаалга нээгдлээ гэж хэвлэ.','keys = 3\nif keys >= 3:\n    # Догол мөрөнд хэвлээрэй\n','keys = 3\nif keys >= 3:\n    print("Хаалга нээгдлээ")','Хаалга нээгдлээ','assert has("If"), "if нөхцөл ашиглаарай."',['if мөрийн төгсгөлд : байна.','Дараагийн мөр 4 зайтай эхэлж print("Хаалга нээгдлээ") байна.']);
lesson(1,'Хоёр зам','else','if нөхцөл худал бол else хэсэг ажиллана. else: нь if-тэй нэг түвшний доголтой байна.','energy = 0 үед Амар, бусад үед Алх гэж хэвлэдэг нөхцөл бич.','energy = 0\n# if / else ашиглаарай\n','energy = 0\nif energy > 0:\n    print("Алх")\nelse:\n    print("Амар")','Амар','assert has("If") and any(isinstance(n, ast.If) and n.orelse for n in ast.walk(tree)), "else салаа нэмээрэй."',['if energy > 0: гэж эхэл.','else: дотор print("Амар") бич.']);
lesson(1,'Нууц үг','== харьцуулалт','= нь оноох, == нь тэнцүү эсэхийг шалгах үйлдэл. Текстийн том жижиг үсэг ялгаатай.','password нь python байвал Зөв гэж хэвлэ.','password = "python"\n','password = "python"\nif password == "python":\n    print("Зөв")','Зөв','assert has("Eq") and has("If"), "== харьцуулалттай if бичээрэй."',['if password == "python":','Дотор нь print("Зөв") бич.']);
lesson(1,'Хос түлхүүр','and / or','and нь хоёр нөхцөл хоёулаа үнэн эсэхийг шалгана. or нь ядаж нэг нь үнэн байхад үнэн. True ба False нь логик утгууд.','has_key болон has_map хоёулаа үнэн үед Бэлэн гэж хэвлэ.','has_key = True\nhas_map = True\n','has_key = True\nhas_map = True\nif has_key and has_map:\n    print("Бэлэн")','Бэлэн','assert has("And"), "and ашиглан хоёр нөхцөлийг холбоорой."',['if has_key and has_map:','Нөхцөлийн доор 4 зайтай print("Бэлэн") бич.']);
lesson(1,'Гурван зэрэг','elif','Олон сонголтод elif хэрэглэнэ. Нөхцөлийг дээрээс доош шалгаад эхний үнэн салааг ажиллуулна.','score >= 80 бол Алт, >= 50 бол Мөнгө, бусад үед Хүрэл гэж хэвлэ. score = 65.','score = 65\n','score = 65\nif score >= 80:\n    print("Алт")\nelif score >= 50:\n    print("Мөнгө")\nelse:\n    print("Хүрэл")','Мөнгө','assert count("If") >= 2, "if, elif гэсэн хоёр шалгалт хэрэгтэй."',['Өндөр босгоо эхэлж шалга.','elif score >= 50: дотор print("Мөнгө") байна.']);
lesson(1,'Ойн харуул','Нөхцөлийн сорил','Функцээ дуудсан бол үр дүнг нь нөхцөлд шалгаж болно. can_move() нь урд нүд рүү алхаж болох эсэхийг буцаана.','if can_move(): ашиглан нэг алх. Дараа нь collect() хий.','if can_move():\n    # Алхаарай\ncollect()','if can_move():\n    move()\ncollect()','','assert has("If"), "if ашиглаарай."',['can_move() үнэн үед move() дууд.','Догол мөрөнд move() бич.'],{game:{width:5,start:0,coins:[1],goal:1},boss:true});
lesson(2,'Гурван алхам','for / range','for i in range(3): нь гурван удаа давтана. i нь 0, 1, 2 утгыг дарааллаар авна. Доторх код 4 зайтай байна.','Алхам гэдэг үгийг 3 удаа, тус бүр шинэ мөрөнд хэвлэ.','for i in range(3):\n    # Энд хэвлээрэй\n','for i in range(3):\n    print("Алхам")','Алхам\nАлхам\nАлхам','assert has("For"), "for давталт хэрэглээрэй."',['Давталтын биед print() байрлана.','print("Алхам")']);
lesson(2,'Тоон шат','range-ийн хязгаар','range(1, 5) нь 1-ээс эхлээд 5 хүрэхгүй: 1, 2, 3, 4. Эцсийн хязгаар орохгүй.','1-ээс 5 хүртэлх тоонуудыг тус тус шинэ мөрөнд хэвлэ.','# for давталт бичээрэй\n','for n in range(1, 6):\n    print(n)','1\n2\n3\n4\n5','assert has("For"), "for давталтаар тоолоорой."',['5-ыг оруулахын тулд эцсийн хязгаар 6 байна.','range(1, 6)']);
lesson(2,'Зоосны цуваа','Нийлбэр хуримтлуулах','total += n нь total дээр n-ийг нэмээд хадгална. Давталтын өмнө total = 0 гэж эхэлнэ.','1-ээс 5 хүртэлх тоог for давталтаар нэмж total-д хадгалан хэвлэ.','total = 0\n# Энд давталтаа бичээрэй\nprint(total)','total = 0\nfor n in range(1, 6):\n    total += n\nprint(total)','15','assert has("For") and g.get("total") == 15, "Давталтаар total-ийг тооцоолоорой."',['Давталт дотор total += n бич.','print(total) нь давталтын дараа, доголгүй байна.']);
lesson(2,'Унтдаггүй харуул','while','while нь нөхцөл үнэн байгаа хугацаанд давтана. Тоолуураа өөрчлөхгүй бол төгсгөлгүй давталт үүснэ. Зогсоох товчоор тасалж болно.','count = 3-аас эхлээд 3, 2, 1 гэж хэвлэж, удаа бүр 1-ээр багасга.','count = 3\nwhile count > 0:\n    print(count)\n    # Тоолуурыг бууруулаарай\n','count = 3\nwhile count > 0:\n    print(count)\n    count -= 1','3\n2\n1','assert has("While") and g.get("count") == 0, "while давталтаа 0 дээр зогсоогоорой."',['count -= 1 нь нэгээр бууруулна.','Тэр мөр давталтын дотор 4 зайтай байна.']);
lesson(2,'Тэгш чулуу','% үлдэгдэл','n % 2 нь 2-т хуваахад гарах үлдэгдэл. Үлдэгдэл 0 бол тэгш тоо. if-ийг for дотор бичиж болно.','1-ээс 6 хүртэл давтаад зөвхөн тэгш тоонуудыг хэвлэ.','for n in range(1, 7):\n    # Тэгш эсэхийг шалгаарай\n','for n in range(1, 7):\n    if n % 2 == 0:\n        print(n)','2\n4\n6','assert has("For") and has("If") and has("Mod"), "for, if, % гурвыг ашиглаарай."',['if n % 2 == 0: мөр 4 зайтай байна.','Түүний print(n) мөр 8 зайтай байна.']);
lesson(2,'Уулын гүүр','Давталтын сорил','Олон ижил командыг давталтаар богиносгоно. Зоос байгаа нүд бүрт очоод цуглуулах хэрэгтэй.','for давталтаар 4 удаа алхаж, алхам бүрийн дараа зоосоо ав.','# for ашиглаарай\n','for i in range(4):\n    move()\n    collect()','','assert has("For"), "Дөрвөн ижил командыг for-оор давтаарай."',['range(4) ашигла.','Дотор нь move(), collect() хоёр мөр бич.'],{game:{width:6,start:0,coins:[1,2,3,4],goal:4},boss:true});
lesson(3,'Аялагчийн цүнх','Жагсаалт','Жагсаалт нь олон утгыг [ ] дотор таслалаар тусгаарлаж хадгална. for item in bag: гэж зүйл бүрээр давтана.','Цүнхний зүйлсийг дарааллаар нь тус тус хэвлэ.','bag = ["Газрын зураг", "Түлхүүр", "Алим"]\n','bag = ["Газрын зураг", "Түлхүүр", "Алим"]\nfor item in bag:\n    print(item)','Газрын зураг\nТүлхүүр\nАлим','assert has("For") and isinstance(g.get("bag"), list), "Жагсаалтаар давтаарай."',['for item in bag:','Дотор нь print(item) бич.']);
lesson(3,'Эхний эрдэнэ','Индекс','Python жагсаалтын индекс 0-ээс эхэлнэ. bag[0] нь эхний, bag[1] нь хоёр дахь зүйл.','gems жагсаалтын эхний болон сүүлийн зүйлийг тус тус хэвлэ.','gems = ["Бадмаараг", "Болор", "Алмаз"]\n','gems = ["Бадмаараг", "Болор", "Алмаз"]\nprint(gems[0])\nprint(gems[-1])','Бадмаараг\nАлмаз','assert count("Subscript") >= 2, "Индексээр хоёр зүйлээ аваарай."',['Эхний индекс 0. Сүүлийн индекс -1 байж болно.','print(gems[0]) ба print(gems[-1])']);
lesson(3,'Цүнхээ дүүргэе','append / len','bag.append("Алим") нь төгсгөлд зүйл нэмнэ. len(bag) нь зүйлийн тоог буцаана.','bag-д Алим нэмээд жагсаалтын уртыг хэвлэ.','bag = ["Газрын зураг", "Түлхүүр"]\n','bag = ["Газрын зураг", "Түлхүүр"]\nbag.append("Алим")\nprint(len(bag))','3','assert g.get("bag") == ["Газрын зураг", "Түлхүүр", "Алим"], "bag-д Алим нэмээрэй."',['bag.append("Алим")','Дараа нь print(len(bag))']);
lesson(3,'Нууц бичиг','Текстийн арга','Текстийн .upper() арга үсгийг том болгоно. .lower() жижиг болгоно. Эдгээр нь шинэ текст буцаадаг.','message дахь python quest текстийг том үсгээр хэвлэ.','message = "python quest"\n','message = "python quest"\nprint(message.upper())','PYTHON QUEST','assert any(isinstance(n, ast.Attribute) and n.attr == "upper" for n in ast.walk(tree)), "upper() ашиглаарай."',['message.upper() шинэ текст өгнө.','print(message.upper())']);
lesson(3,'Баатрын бүртгэл','Dictionary','Толь буюу dict нь түлхүүр: утга хос хадгална. hero["name"] гэж түлхүүрээр нь утгыг авна.','hero-ийн name болон level утгуудыг тус тус хэвлэ.','hero = {"name": "Ану", "level": 5}\n','hero = {"name": "Ану", "level": 5}\nprint(hero["name"])\nprint(hero["level"])','Ану\n5','assert isinstance(g.get("hero"), dict) and count("Subscript") >= 2, "Толь дотроос түлхүүрээр утгаа аваарай."',['hero["name"] нь Ану.','hero["level"] нь 5.']);
lesson(3,'Агуйн эрдэнэс','Өгөгдлийн сорил','Жагсаалтаар давтаж, нөхцөлөөр шүүж, нийлбэр хуримтлуулж болно.','values жагсаалтын 10-аас их буюу тэнцүү тоонуудыг нэмж total-д хадгалан хэвлэ.','values = [5, 10, 3, 20, 15]\ntotal = 0\n# Давталт ба нөхцөлөө бичээрэй\nprint(total)','values = [5, 10, 3, 20, 15]\ntotal = 0\nfor value in values:\n    if value >= 10:\n        total += value\nprint(total)','45','assert has("For") and has("If") and g.get("total") == 45, "Жагсаалтыг давталт, нөхцөлөөр шүүгээрэй."',['for value in values: дотор if value >= 10: бич.','if дотор total += value бич.'],{boss:true});
lesson(4,'Шидэт мэндчилгээ','def','def нь нэртэй, дахин ашиглах үйлдэл үүсгэнэ. def greet(): гэж тодорхойлоод greet() гэж дуудна.','greet() функц үүсгэ. Дуудах бүрд Сайн уу, аялагч! гэж хэвлэх ёстой. Нэг удаа дууд.','# Функцээ энд тодорхойлоорой\n\ngreet()','def greet():\n    print("Сайн уу, аялагч!")\ngreet()','Сайн уу, аялагч!','assert callable(g.get("greet")), "greet функцийг үүсгээрэй."\nwith contextlib.redirect_stdout(io.StringIO()) as capture:\n    g["greet"]()\nassert capture.getvalue().strip() == "Сайн уу, аялагч!", "greet() өөрөө мэндчилгээг хэвлэх ёстой."',['def greet(): гэж эхэл.','Дотор нь print("Сайн уу, аялагч!") бич.']);
lesson(4,'Хоёр дахин хүч','return','Параметр нь функцэд өгсөн оролт. return нь тооцсон утгыг буцаана. print нь хэвлэдэг, return нь үр дүнг буцаадаг.','double(n) функц n-ийг 2 дахин өсгөж буцаадаг болго. double(7)-г хэвлэ.','def double(n):\n    return n\n\nprint(double(7))','def double(n):\n    return n * 2\n\nprint(double(7))','14','assert callable(g.get("double")), "double функц үүсгээрэй."\nfor n in [0, 3, -4, 11]:\n    assert g["double"](n) == n * 2, f"double({n}) буруу үр дүн өглөө."',['return n * 2','Функцийг бусад тоон дээр бас шалгана.']);
lesson(4,'Хоёр зоосны нийлбэр','Олон параметр','Функц олон оролт авч болно: def add(a, b):. Оролтуудыг таслалаар тусгаарлана.','add(a, b) функц хоёр тооны нийлбэр буцаадаг болго. add(12, 8)-г хэвлэ.','def add(a, b):\n    return 0\n\nprint(add(12, 8))','def add(a, b):\n    return a + b\n\nprint(add(12, 8))','20','assert callable(g.get("add"))\nfor a,b in [(1,2),(-5,7),(0,0)]:\n    assert g["add"](a,b) == a+b, "add өөр оролт дээр буруу байна."',['a ба b хоёр хувьсагчийг нэмнэ.','return a + b']);
lesson(4,'Харуулын шийдвэр','Логик буцаах','Функц True эсвэл False буцааж болно. n % 2 == 0 илэрхийлэл өөрөө логик утгатай.','is_even(n) тэгш тоонд True, сондгой тоонд False буцаадаг болго. is_even(6)-г хэвлэ.','def is_even(n):\n    return False\n\nprint(is_even(6))','def is_even(n):\n    return n % 2 == 0\n\nprint(is_even(6))','True','assert callable(g.get("is_even"))\nfor n in [0,1,2,7,-4]:\n    assert g["is_even"](n) is (n % 2 == 0), "Тэгш ба сондгой тоог хоёуланг шалгаарай."',['Үлдэгдэл 0 байвал тэгш.','return n % 2 == 0']);
lesson(4,'Багийн хүч','Функц ба жагсаалт','Функц жагсаалт авч болно. total = 0-ээс эхлээд тоо бүрийг нэмэж, төгсгөлд return хийнэ.','total_coins(coins) жагсаалтын нийлбэр буцаадаг болго. [10, 20, 30] дээр хэвлэ.','def total_coins(coins):\n    total = 0\n    # Давталтаа бичээрэй\n    return total\n\nprint(total_coins([10, 20, 30]))','def total_coins(coins):\n    total = 0\n    for coin in coins:\n        total += coin\n    return total\n\nprint(total_coins([10, 20, 30]))','60','assert has("For") and callable(g.get("total_coins"))\nfor items in [[],[1],[3,7,9],[-2,5]]:\n    assert g["total_coins"](items) == sum(items), "Өөр жагсаалт дээр нийлбэр буруу байна."',['Функц доторх for мөр 4 зайтай.','total += coin мөр 8 зайтай. return total нь давталтын гадна байна.']);
lesson(4,'Цайзын эзэн','Төгсгөлийн сорил','Функц + давталт + тоглоомын команд. Нэг чадвараа бүтээгээд олон удаа дуудъя. jump() хоёр нүд алгасаж үсэрнэ.','cross() функц дотор jump(), collect() дууд. for давталтаар cross()-г 3 удаа ажиллуулж бүх эрдэнэсийг ав.','def cross():\n    # Үсрээд эрдэнэсээ ав\n    pass\n\n# cross()-г 3 удаа давтаарай\n','def cross():\n    jump()\n    collect()\n\nfor i in range(3):\n    cross()','','assert has("FunctionDef") and has("For"), "Функцээ үүсгээд for давталтаар дуудаарай."',['jump() хоёр нүд урагшилна.','cross() дотор jump(), collect(); гадна нь for i in range(3): ба cross().'],{game:{width:8,start:0,coins:[2,4,6],goal:6,holes:[1,3,5]},boss:true});
